const db = require('better-sqlite3')('world.db');

// Step 1: Reverse the return on ITEM-70E770 and set to exchanged
console.log('=== STEP 1: Reverse return & mark as exchanged ===');
const updateItem = db.prepare(\`
  UPDATE order_items SET
    item_status = 'exchanged',
    return_reason = NULL,
    refund_amount = 0,
    refund_method = NULL,
    return_label_issued = 0,
    replacement_item_id = 'PROD-2DBA15'
  WHERE oi_id = 'ITEM-70E770' AND order_id = 'ORD-5B048F'
\`);
const itemResult = updateItem.run();
console.log('Order item updated:', itemResult.changes, 'row(s)');

// Step 2: Update order-level exchange fields
console.log('\n=== STEP 2: Update order-level exchange fields ===');
const updateOrder = db.prepare(\`
  UPDATE orders SET
    exchange_items = 'ITEM-70E770',
    exchange_new_items = 'PROD-2DBA15',
    exchange_price_difference = 10,
    exchange_payment_method_id = 'credit_card_9958253'
  WHERE order_id = 'ORD-5B048F'
\`);
const orderResult = updateOrder.run();
console.log('Order updated:', orderResult.changes, 'row(s)');

// Step 3: Verify the changes
console.log('\n=== VERIFICATION ===');
const item = db.prepare(\"SELECT * FROM order_items WHERE oi_id = 'ITEM-70E770'\").get();
console.log('\nUpdated Item:');
console.log(JSON.stringify(item, null, 2));

const order = db.prepare(\`
  SELECT order_id, exchange_items, exchange_new_items, 
         exchange_price_difference, exchange_payment_method_id 
  FROM orders WHERE order_id = 'ORD-5B048F'
\`).get();
console.log('\nUpdated Order Exchange Fields:');
console.log(JSON.stringify(order, null, 2));

// Also verify the new product details for the log
