cd /workspace && node -e "
const AdmZip = require('adm-zip');
const zip = new AdmZip('testbed/docs/customer_report.docx');
let xml = zip.readAsText('word/document.xml');

// Today's date
const today = new Date().toISOString().split('T')[0];

// Build the exchange log entry paragraphs
const exchangeLog = [
  // Heading
  '<w:p><w:pPr><w:pStyle w:val=\"Heading1\"/></w:pPr><w:r><w:t>Exchange Log</w:t></w:r></w:p>',
  // Divider
  '<w:p><w:r><w:t>————————————————————————————————</w:t></w:r></w:p>',
  // Order & Date
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Order:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> ORD-5B048F</w:t></w:r></w:p>',
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Customer:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> Maya Chen (user_d3d5d0c8)</w:t></w:r></w:p>',
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Exchange Date:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> ' + today + '</w:t></w:r></w:p>',
  // Original item
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Original Item:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> LogiTech Wireless Mouse M310 (PROD-FA0948) — \$29</w:t></w:r></w:p>',
  // Replacement item
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Replacement Item:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> Wireless Ergonomic Mouse (PROD-2DBA15) — \$39</w:t></w:r></w:p>',
  // Price difference
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Price Difference:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> +\$10 charged to Visa ending 4242 (credit_card_9958253)</w:t></w:r></w:p>',
  // Status
  '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>Status:</w:t></w:r><w:r><w:t xml:space=\"preserve\"> Exchange completed</w:t></w:r></w:p>',
  // Divider
  '<w:p><w:r><w:t>————————————————————————————————</w:t></w:r></w:p>',
].join('');

// Insert before </w:sectPr> (before the section properties / end of body)
xml = xml.replace('<w:sectPr', exchangeLog + '<w:sectPr');

// Write updated XML back into the docx
zip.updateFile('word/document.xml', Buffer.from(xml, 'utf-8'));
zip.writeZip('testbed/docs/customer_report.docx');
console.log('customer_report.docx updated successfully!');
"

